import {
  Box,
  Flex,
  Text,
  Heading,
  ListItem,
  UnorderedList,
  useColorModeValue
} from '@chakra-ui/react';
import React from 'react';
import Styles from './GitHubStats.module.css';
import { pointers } from '../Utils/constants';

const About = () => {
  const containerBg = useColorModeValue('#e9d8fd', '#11041c');
  const listItemTextColor = useColorModeValue('gray.800', 'gray.400');

  return (
    <Box
      height='100vh'
      bg={containerBg}
      id='about'
      className='about section'
      px={{ base: '8', sm: '16', lg: '20' }}
      pt={{ base: '4', sm: '8', md: '12' }}
      pb={{ base: '8', sm: '12', md: '24' }}
    >
      <Flex
        className={Styles.gitCalHeadingWrapper}
        mb={{ base: '6', sm: '8', md: '10', lg: '12' }}
        gap={{ base: '2', sm: '4', lg: '6' }}
      >
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          About
        </Heading>
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Me
        </Heading>
      </Flex>

      <UnorderedList
        id='user-detail-intro'
        spacing={{ base: 4, sm: 3, md: 4, lg: 4, xl: 3 }}
        w={{ base: '90%', sm: '95%', md: '90%', lg: '90%', xl: '80%' }}
        m='auto'
      >
        {pointers.map((pointer, i) => (
          <ListItem key={i}>
            <Text
              color={listItemTextColor}
              fontSize={{
                base: 'sm',
                sm: 'md',
                mdr: 'md',
                md: 'lg',
                lg: 'lg',
                xl: 'lg'
              }}
              fontWeight={'semibold'}
              textAlign={'justify'}
            >
              {pointer}
            </Text>
          </ListItem>
        ))}
      </UnorderedList>
    </Box>
  );
};

export default About;
