import {
  Box,
  Text,
  Link,
  Flex,
  Stack,
  Heading,
  SimpleGrid,
  useColorModeValue,
} from '@chakra-ui/react';
import React from 'react';
import Styles from './GitHubStats.module.css';
import { FaEnvelope, FaGithub, FaLinkedin, FaMobileAlt } from 'react-icons/fa';

const Contact = () => {
  const containerBg = useColorModeValue('#e9d8fd', '#11041c');

  return (
    <Box
      id='contact'
      bg={containerBg}
      px={{ base: '8', sm: '16', lg: '20' }}
      pt={{ base: '4', sm: '8', md: '12' }}
      pb={{ base: '8', sm: '12', md: '24' }}
    >
      <Flex
        className={Styles.gitCalHeadingWrapper}
        mb={{ base: '6', sm: '8', md: '10', lg: '12' }}
        gap={{ base: '2', sm: '4', lg: '6' }}
      >
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Contact
        </Heading>
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Me
        </Heading>
      </Flex>

      <SimpleGrid
        columns={{ base: 1, sm: 2, lg: 4 }}
        justifyContent={'center'}
        alignItems={'center'}
        spacingY={{ base: 10, sm: 12, md: '16', lg: 0 }}
      >
        <Stack
          id='contact-email'
          maxW='min-content'
          m='auto'
          p='2'
          alignItems='center'
          spacing={{ base: 1, sm: 1, lg: 0 }}
        >
          <Link
            style={{ textDecoration: 'none' }}
            href='mailto:sanket.potdar563@gmail.com'
          >
            <Text color={'#6e0dd0'}>
              <FaEnvelope />
            </Text>
          </Link>
          <Heading
            pt={{ base: 1, sm: 2, md: 4 }}
            size={{ base: 'xs', sm: 'md' }}
          >
            Email:
          </Heading>
          <Link
            style={{ textDecoration: 'none' }}
            href='mailto:sanket.potdar563@gmail.com'
          >
            <Text
              noOfLines={1}
              display='inline'
              whiteSpace='nowrap'
              textOverflow='hidden'
              fontSize={{ base: 'xs', sm: 'sm' }}
            >
              sanket.potdar563@gmail.com
            </Text>
          </Link>
        </Stack>

        <Stack
          id='contact-phone'
          maxW='min-content'
          m='auto'
          p='2'
          alignItems='center'
          spacing={{ base: 1, sm: 1, lg: 0 }}
        >
          <Link style={{ textDecoration: 'none' }} href='tel:+91.8308003869'>
            <Text color={'#6e0dd0'}>
              <FaMobileAlt />
            </Text>
          </Link>
          <Heading
            pt={{ base: 1, sm: 2, md: 4 }}
            size={{ base: 'xs', sm: 'md' }}
          >
            Mobile:
          </Heading>
          <Link style={{ textDecoration: 'none' }} href='tel:+91.8308003869'>
            <Text
              noOfLines={1}
              display='inline'
              whiteSpace='nowrap'
              textOverflow='hidden'
              fontSize={{ base: 'xs', sm: 'sm' }}
            >
              +91-8308003869
            </Text>
          </Link>
        </Stack>

        <Stack
          id='contact-github'
          maxW='min-content'
          m='auto'
          p='2'
          alignItems='center'
          spacing={{ base: 1, sm: 1, lg: 0 }}
        >
          <Link
            style={{ textDecoration: 'none' }}
            href='https://github.com/SanketPotdar121695'
            isExternal
          >
            <Text color={'#6e0dd0'}>
              <FaGithub />
            </Text>
          </Link>
          <Heading
            pt={{ base: 1, sm: 2, md: 4 }}
            size={{ base: 'xs', sm: 'md' }}
          >
            GitHub:
          </Heading>
          <Link
            style={{ textDecoration: 'none' }}
            href='https://github.com/SanketPotdar121695'
            isExternal
          >
            <Text display='inline' fontSize={{ base: 'xs', sm: 'sm' }}>
              SanketPotdar121695
            </Text>
          </Link>
        </Stack>

        <Stack
          id='contact-linkedin'
          maxW='min-content'
          m='auto'
          p='2'
          alignItems='center'
          spacing={{ base: 1, sm: 1, lg: 0 }}
        >
          <Link
            style={{ textDecoration: 'none' }}
            href='https://www.linkedin.com/in/sanket-potdar563/'
            isExternal
          >
            <Text color={'#6e0dd0'}>
              <FaLinkedin />
            </Text>
          </Link>
          <Heading
            pt={{ base: 1, sm: 2, md: 4 }}
            size={{ base: 'xs', sm: 'md' }}
          >
            LinkedIn:
          </Heading>
          <Link
            style={{ textDecoration: 'none' }}
            href='https://www.linkedin.com/in/sanket-potdar563/'
            isExternal
          >
            <Text
              noOfLines={1}
              display='inline'
              whiteSpace='nowrap'
              textOverflow='hidden'
              fontSize={{ base: 'xs', sm: 'sm' }}
            >
              sanket-potdar563
            </Text>
          </Link>
        </Stack>
      </SimpleGrid>
    </Box>
  );
};

export default Contact;
