import {
  Box,
  Flex,
  Text,
  Icon,
  Link,
  Badge,
  Image,
  Button,
  Tooltip,
  Heading,
  SimpleGrid,
  useColorModeValue,
} from '@chakra-ui/react';
import React from 'react';
import Styles from './GitHubStats.module.css';
import { projectInfo } from '../Utils/constants';
import { FaEye, FaGithub } from 'react-icons/fa';

const Projects = () => {
  const containerBg = useColorModeValue('#e9d8fd', '#11041c');
  const projectCardBoxShadow = useColorModeValue(
    'rgba(0, 0, 0, 0.4) 0px 0px 15px',
    'rgba(110, 13, 208, 0.4) 0px 0px 15px'
  );
  const projectCardBoxShadowOnHover = useColorModeValue(
    'rgba(0, 0, 0, 0.6) 0px 0px 30px',
    'rgba(192, 26, 192, 0.8) 0px 0px 30px'
  );
  const headerTextColor = useColorModeValue('#6e0dd0', '#c01ac0');
  const toolTipBg = useColorModeValue('#300a47', 'purple.300');
  const badgeColor = useColorModeValue('solid', 'subtle');

  return (
    <Box
      id='projects'
      bg={containerBg}
      px={{ base: '8', sm: '12', md: '16', lg: '20' }}
      pt={{ base: '4', sm: '8', md: '12' }}
      pb={{ base: '8', sm: '12', md: '24' }}
    >
      <Flex
        className={Styles.gitCalHeadingWrapper}
        mb={{ base: '6', sm: '8', md: '10', lg: '12' }}
        gap={{ base: '2', sm: '4', lg: '6' }}
      >
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          My
        </Heading>
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Projects
        </Heading>
      </Flex>

      <SimpleGrid
        columns={{ base: 1, md: 2, lg: 3 }}
        justifyContent={'center'}
        alignItems='center'
        spacingX={8}
        spacingY={12}
        px={{ base: '0', xl: '8' }}
      >
        {projectInfo.map((project, i) => (
          <Box
            key={i}
            className='project-card'
            boxShadow={projectCardBoxShadow}
            p='4'
            w={{ base: '90%', sm: '80%', md: '95%' }}
            m='auto'
            _hover={{
              boxShadow: projectCardBoxShadowOnHover,
              transform: 'scale(1.01)'
            }}
            transition='0.5s'
            borderRadius={16}
          >
            <Image
              className='project-title'
              borderTopRadius={10}
              src={project.img_url}
              alt={project.alt}
            />

            <Box
              h={{
                base: '50px',
                sm: '55px',
                md: '65px',
                lg: '60px',
                xl: '50px'
              }}
              mt={{ base: '8', sm: '6', lg: '8' }}
              mb={2}
            >
              <Heading
                letterSpacing={{ base: 'short', xl: 'normal' }}
                size={{ base: 'sm', sm: 'md', lg: 'sm', xl: 'md' }}
                textAlign={'left'}
              >
                {project.title}
              </Heading>
            </Box>

            <Box h={{ base: '70px', md: '75px', lg: '80px' }}>
              <Text
                className='project-description'
                lineHeight={{ base: 'short', sm: 'shorter', md: 'short' }}
                fontWeight={'semibold'}
                textAlign={'justify'}
                letterSpacing={{ base: 'short', xl: 'normal' }}
                fontSize={{
                  base: 'xs',
                  xs: 'sm',
                  sm: 'md',
                  lg: 'sm',
                  xl: 'sm'
                }}
              >
                {project.description}
              </Text>
            </Box>

            <Flex
              className='project-tech-stack'
              justifyContent={'left'}
              alignItems={'flext-start'}
              gap='2'
              h={{ base: '70px', lg: '80px' }}
            >
              <Text
                letterSpacing={{ base: 'short', xl: 'normal' }}
                fontSize={{
                  base: 'xs',
                  xs: 'sm',
                  md: 'md'
                }}
                color={headerTextColor}
                fontWeight={'semibold'}
                whiteSpace={'nowrap'}
                display={'inline'}
              >
                Tech Stack:{' '}
              </Text>

              <Flex
                h='0'
                justifyContent={'left'}
                alignItems='flex-start'
                gap={{ base: '1', sm: '2' }}
                flexFlow={'wrap'}
                mt='1'
              >
                {project.tech_stack.map((tech, j) => (
                  <Badge
                    key={Date.now() * j}
                    letterSpacing={{ base: 'short', xl: 'normal' }}
                    fontSize={{
                      base: '8px',
                      xs: '10px',
                      sm: '11px',
                      xl: '12px'
                    }}
                    variant={badgeColor}
                    colorScheme={tech.color}
                  >
                    {tech.content}
                  </Badge>
                ))}
              </Flex>
            </Flex>

            <Flex
              justifyContent={'space-between'}
              alignItems={'center'}
              px={{ base: '1', sm: '2', md: '4' }}
            >
              <Tooltip
                openDelay={500}
                placement={'bottom'}
                hasArrow
                label='Visit Project'
                bg={toolTipBg}
              >
                <Button
                  bg='none'
                  _hover={{ bg: 'none' }}
                  className='project-github-link'
                >
                  <Link href={project.deployed_url} isExternal>
                    <Icon boxSize={6} as={FaEye} cursor='pointer' />
                  </Link>
                </Button>
              </Tooltip>

              <Tooltip
                openDelay={500}
                placement={'bottom'}
                hasArrow
                label='Visit Codebase'
                bg={toolTipBg}
              >
                <Button
                  bg='none'
                  _hover={{ bg: 'none' }}
                  className='project-deployed-link'
                >
                  <Link href={project.codebase_url} isExternal>
                    <Icon boxSize={6} as={FaGithub} cursor='pointer' />
                  </Link>
                </Button>
              </Tooltip>
            </Flex>
          </Box>
        ))}
      </SimpleGrid>
    </Box>
  );
};

export default Projects;
