import React from 'react';
import { Text, Heading, useColorModeValue, Stack } from '@chakra-ui/react';

const Footer = () => {
  const containerBg = useColorModeValue('purple.300', '#330352');

  return (
    <Stack
      pos='relative'
      zIndex='1500'
      justifyContent={'center'}
      alignItems={'center'}
      spacing={{ base: 3, md: 6 }}
      py={{ base: '6', sm: '8' }}
      bg={containerBg}
      id='footer'
    >
      <Text
        fontFamily='sans-serif'
        fontSize={{ base: 'xs', sm: 'md' }}
        letterSpacing='wider'
      >
        👨‍💻 Made by Sanket Potdar
      </Text>

      <Heading
        fontStyle='italic'
        fontFamily={'cursive,Verdana, Geneva, Tahoma, sans-serif;'}
        size={{ base: 'md', sm: 'lg' }}
      >
        Thank you for visiting.
      </Heading>

      <Text fontSize={{ base: 'xs', sm: 'md' }}>
        &copy; {new Date().getFullYear()}, All rights reserved
      </Text>
    </Stack>
  );
};

export default Footer;
