import React from 'react';
import { testingSkillSet } from "../../Utils/constants";
import { Box, Text, Image, useColorModeValue, } from '@chakra-ui/react';

export const TestingSkills = () => {
  const containerBoxShadow = useColorModeValue(
    'rgba(0, 0, 0, 0.4) 0px 0px 15px',
    'rgba(110, 13, 208, 0.4) 0px 0px 15px'
  );
  const containerBoxShadowOnHover = useColorModeValue(
    'rgba(0, 0, 0, 0.6) 0px 0px 30px',
    'rgba(192, 26, 192, 0.8) 0px 0px 30px'
  );
  const imgBg = useColorModeValue('auto', 'white');

  return (
    <>
      {testingSkillSet.map(({ title, img_url, alt }, i) => {
        return (
          <Box
            className='skills-card'
            key={i}
            py={{ base: 3, sm: 6 }}
            w={{ base: '80px', sm: '120px', md: '150px', lg: '200px' }}
            m='auto'
            fontWeight='medium'
            letterSpacing='wide'
            boxShadow={containerBoxShadow}
            _hover={{ boxShadow: containerBoxShadowOnHover, transform: 'scale(1.1)' }}
            transition='0.5s'
            borderRadius={16}
          >
            <Image
              className='skills-card-img'
              src={img_url}
              alt={alt}
              w={{ base: '30px', sm: '40px', md: '60px', lg: '80px' }}
              padding={alt === 'Cypress' ? '2' : 'auto'}
              borderRadius={alt === 'Cypress' ? "50%" : "auto"}
              background={alt === 'Cypress' ? imgBg : 'auto'}
            />
            <Text
              className='skills-card-name'
              mt={{ base: '2', sm: '4' }}
              fontSize={{ base: 'xs', lg: 'md' }}
            >
              {title}
            </Text>
          </Box>
        );
      })}
    </>
  );
};