import {
  Box,
  Flex,
  Text,
  Link,
  Image,
  Stack,
  Button,
  Heading,
  useColorModeValue
} from '@chakra-ui/react';
import React from 'react';
import Typewriter from 'typewriter-effect';
import Styles from './GitHubStats.module.css';
import { resumeLink } from '../Utils/constants';
import { Link as AnchorLink } from 'react-scroll';
import MyPic from '../Assets/legend-transparent2.png';
import MyResume from '../Assets/Sanket_Potdar_Resume.pdf';

const Home = () => {
  const handleResume = () => {
    window.open(resumeLink);
  };

  const changeSectionOffset = () => {
    let w = window.screen.width;
    if (w <= 480) return -42;
    if (w > 991) return -78;
    if (w > 768 && w <= 991) return -66;
    if (w > 480 && w <= 768) return -50;
  };

  const containerBg = useColorModeValue('#e9d8fd', '#11041c');
  const btnBorderColor = useColorModeValue('#6e0dd0', '#c01ac0');
  const btnBoxShadow = useColorModeValue(
    'rgba(0, 0, 0, 0.4) 0px 0px 15px',
    'rgba(110, 13, 208, 0.4) 0px 0px 15px'
  );
  const btnBoxShadowOnHover = useColorModeValue(
    'rgba(0, 0, 0, 0.6) 0px 0px 30px',
    'rgba(192, 26, 192, 0.8) 0px 0px 30px'
  );
  const imgBoxShadow = useColorModeValue(
    'rgba(0, 0, 0, 0.4) 0px 0px 30px',
    'rgba(110, 13, 208, 0.4) 0px 0px 30px'
  );
  const imgBoxShadowOnHover = useColorModeValue(
    'rgba(107, 70, 193, 0.8) 0px 0px 100px',
    'rgba(110, 13, 208, 0.8) 0px 0px 100px'
  );
  const imgBgGradient = useColorModeValue(
    'radial(circle at center, white 0%, purple.400 100%)',
    'radial(circle at center, white 0%, #6e0dd0 100%)'
  );

  return (
    <Box
      id='home'
      bg={containerBg}
      px={{ base: '4', xs: '8', sm: '16', lg: '20', xl: '32' }}
      py={{ base: '8', sm: '16', md: '20', lg: '24', xl: '32' }}
    >
      <Stack
        flexFlow={{ base: 'column-reverse', md: 'auto' }}
        direction={{ base: 'column', md: 'row' }}
        justifyContent={{ base: 'center', md: 'space-around' }}
        gap={{ base: '12', md: 'auto' }}
        alignItems={'center'}
      >
        <Box
          pl={{ base: 2, xs: 6, sm: 10, mdr: 16, md: 0 }}
          w={{
            base: '100%',
            md: '60%',
            lg: '50%'
          }}
        >
          <Flex
            id='user-detail-name'
            justifyContent={'left'}
            alignItems={'center'}
            gap='3'
          >
            <Heading
              size={{
                base: 'xs',
                xs: 'sm',
                mdr: 'md',
                lg: 'lg'
              }}
              fontWeight={'medium'}
            >
              Hello, my name is{' '}
            </Heading>

            <Typewriter
              options={{
                strings: ['Sanket Potdar'],
                autoStart: true,
                loop: true,
                delay: 150,
                deleteSpeed: 50,
                wrapperClassName: Styles.typedWrapper,
                cursorClassName: Styles.typedCursor
              }}
            />
          </Flex>

          <Flex justifyContent={'left'} alignItems={'center'} gap='3'>
            <Heading
              size={{
                base: 'xs',
                xs: 'sm',
                mdr: 'md',
                lg: 'lg'
              }}
              fontWeight={'medium'}
            >
              I'm a{' '}
            </Heading>

            <Typewriter
              options={{
                strings: ['Full-stack Web Developer'],
                autoStart: true,
                loop: true,
                delay: 150,
                deleteSpeed: 50,
                wrapperClassName: Styles.typedWrapper,
                cursorClassName: Styles.typedCursor
              }}
            />
          </Flex>

          <Flex
            w={{
              base: '80%',
              xs: '80%',
              sm: '80%',
              mdr: '65%',
              md: '60%',
              lg: '70%',
              xl: '80%'
            }}
            mx={{ base: '0', xs: '2', sm: '2', md: '0', lg: '0', xl: '0' }}
            my='4'
            px={{ base: '0', xl: '4' }}
            ml={{ base: '2', sm: '0', md: '4', lg: '4', xl: '0' }}
            justifyContent={'space-between'}
            alignItems={'center'}
          >
            <Button
              id='resume-button-2'
              bg='none'
              _focus={{ bg: 'none' }}
              _active={{ bg: 'none' }}
              onClick={handleResume}
              border={`2px solid`}
              borderColor={btnBorderColor}
              boxShadow={btnBoxShadow}
              transition='0.5s'
              borderRadius={50}
              _hover={{ boxShadow: btnBoxShadowOnHover, bg: 'none' }}
              fontSize={{ base: 'xs', xs: 'sm', sm: 'sm', md: 'md' }}
            >
              <Link
                id='resume-link-2'
                _hover={{ textDecor: 'none' }}
                href={MyResume}
                download='Sanket_Potdar_Resume'
              >
                <Text>Resume</Text>
              </Link>
            </Button>

            <AnchorLink
              spy={true}
              smooth={true}
              offset={changeSectionOffset()}
              // duration={1000} // Uncomment if needed
              to='contact'
            >
              <Button
                bg='none'
                _focus={{ bg: 'none' }}
                _active={{ bg: 'none' }}
                border={`2px solid`}
                borderColor={btnBorderColor}
                boxShadow={btnBoxShadow}
                transition='0.5s'
                borderRadius={50}
                _hover={{ boxShadow: btnBoxShadowOnHover, bg: 'none' }}
                fontSize={{ base: 'xs', xs: 'sm', sm: 'sm', md: 'md' }}
              >
                Hire me
              </Button>
            </AnchorLink>
          </Flex>
        </Box>

        <Box
          w={{
            base: '60%',
            xs: '45%',
            sm: '55%',
            md: '25%'
          }}
        >
          <Image
            className='home-img'
            boxShadow={imgBoxShadow}
            _hover={{
              boxShadow: imgBoxShadowOnHover,
              transform: 'scale(1.01)'
            }}
            transition='0.5s'
            bgGradient={imgBgGradient}
            borderRadius={'50%'}
            src={MyPic}
            alt='legendary-warrior'
          />
        </Box>
      </Stack>
    </Box>
  );
};

export default Home;
