import {
  Box,
  Tab,
  Tabs,
  Flex,
  TabList,
  Heading,
  TabPanel,
  TabPanels,
  SimpleGrid,
  useColorModeValue,
} from '@chakra-ui/react';
import React from 'react';
import { tabs } from '../../Utils/constants';
import Styles from '../GitHubStats.module.css';
import { BackEndSkills } from './BackEndSkills';
import { FrontEndSkills } from './FrontEndSkills';
import { TestingSkills } from './TestingSkills';

const Skills = () => {
  const tabBgOnSelect = useColorModeValue('purple.300', '#6e0dd0');
  const containerBg = useColorModeValue('#e9d8fd', '#11041c');
  const tabBorder = useColorModeValue(
    '2px solid #6e0dd0',
    '2px solid #c01ac0'
  );

  return (
    <Box
      bg={containerBg}
      id='skills'
      px={{ base: '8', sm: '16', lg: '20' }}
      pt={{ base: '4', sm: '8', md: '12' }}
      pb={{ base: '8', sm: '12', md: '24' }}
    >
      <Flex
        className={Styles.gitCalHeadingWrapper}
        mb={{ base: '6', sm: '8', md: '10', lg: '12' }}
        gap={{ base: '2', sm: '4', lg: '6' }}
      >
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Technical
        </Heading>
        <Heading
          className={Styles.gitCalHeading}
          size={{ base: 'xs', sm: 'md', lg: 'lg' }}
        >
          Skills
        </Heading>
      </Flex>

      <Tabs variant='unstyled' align='center'>
        <TabList>
          {tabs.map((title, i) => (
            <Tab
              key={i}
              px={{ base: '3', sm: '4' }}
              border={tabBorder}
              borderRadius={'md'}
              fontSize={{ base: 'sm', sm: 'md' }}
              // _hover=""
              _selected={{
                bg: tabBgOnSelect,
                border: '2px solid transparent'
              }}
              fontWeight={"semibold"}
              mx={{ base: '1', sm: '4' }}
            >
              {title}
            </Tab>
          ))}
        </TabList>

        <TabPanels>
          <TabPanel>
            <SimpleGrid
              spacingY='16'
              columns={{ base: 2, md: 3 }}
              spacingX={{ base: '8', sm: '4' }}
              py={{ base: '4', sm: '8', lg: '12' }}
            >
              <FrontEndSkills />
              <BackEndSkills />
              <TestingSkills />
            </SimpleGrid>
          </TabPanel>

          <TabPanel>
            <SimpleGrid
              spacingY='16'
              columns={{ base: 2, md: 3 }}
              spacingX={{ base: '8', sm: '4' }}
              py={{ base: '4', sm: '8', lg: '12' }}
            >
              <FrontEndSkills />
            </SimpleGrid>
          </TabPanel>

          <TabPanel>
            <SimpleGrid
              spacingY='16'
              columns={{ base: 2, md: 3 }}
              spacingX={{ base: '8', sm: '4' }}
              py={{ base: '4', sm: '8', lg: '12' }}
            >
              <BackEndSkills />
            </SimpleGrid>
          </TabPanel>

          <TabPanel>
            <SimpleGrid
              spacingY='16'
              columns={{ base: 2, md: 3 }}
              spacingX={{ base: '8', sm: '4' }}
              py={{ base: '4', sm: '8', lg: '12' }}
            >
              <TestingSkills />
            </SimpleGrid>
          </TabPanel>
        </TabPanels>
      </Tabs>
    </Box>
  );
};

export default Skills;
