import React from 'react';
import {
  Flex,
  Show,
  Hide,
  Text,
  Link,
  Button,
  HStack,
  Heading,
  useColorMode
  // Tooltip
} from '@chakra-ui/react';
import Styles from './Navbar.module.css';
import { MoonIcon } from '@chakra-ui/icons';
import MyResume from '../Assets/Sanket_Potdar_Resume.pdf';
import { nav_items, name, resumeLink } from '../Utils/constants';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSun, faDownload } from '@fortawesome/free-solid-svg-icons';
import { Link as AnchorLink, animateScroll as scroll } from 'react-scroll';

const Navbar = () => {
  const [navRoute, setNavRoute] = React.useState('');
  const { colorMode, toggleColorMode } = useColorMode();
  const [nav_bg, setNav_bg] = React.useState(false);

  const changeNavbarBg = () => {
    window.scrollY >= 100 ? setNav_bg(true) : setNav_bg(false);
  };

  const changeSectionOffset = (path) => {
    if (path === 'home') return -100;
    let w = window.screen.width;
    if (w <= 480) return -42;
    if (w > 991) return -78;
    if (w > 768 && w <= 991) return -66;
    if (w > 480 && w <= 768) return -50;
  };

  const finalBg = (a, b, c, d) => {
    return nav_bg
      ? colorMode === 'light'
        ? a
        : b
      : colorMode === 'light'
        ? c
        : d;
  };

  const handleResume = () => {
    window.open(resumeLink);
  };

  window.addEventListener('scroll', changeNavbarBg);
  // window.addEventListener("resize", changeSectionOffset);

  return (
    <>
      <Flex
        id='nav-menu'
        className={Styles.navMenu}
        px={{ base: '2', sm: '4', md: '8' }}
        py={{ base: '1', sm: '1.5', md: '2', lg: '3' }}
        bg={finalBg('purple.300', '#330352', 'white', 'black')}
      // bg='rgba(155, 155, 155, 0.8)'
      >
        <Flex
          id={Styles.legendNameWrapper}
          onClick={() => scroll.scrollToTop()}
          gap={{ base: '0', sm: '1.5', md: '2' }}
        >
          {name.map(({ label }, i) => (
            <Heading
              key={i}
              bgClip='text'
              className={Styles.legendName}
              fontFamily="'Great Vibes', cursive"
              pt='2'
              px={{ base: '1.5', md: '2' }}
              size={{ base: 'sm', sm: 'md', md: 'lg' }}
              bgGradient={
                label === 'Sanket'
                  ? 'linear(to-l, orange.500, pink.600)'
                  : 'linear(to-l, pink.600, orange.500)'
              }
            >
              {label}
            </Heading>
          ))}
        </Flex>

        <HStack spacing={{ base: '1', md: '1', lg: '2' }}>
          <Button
            bg='none'
            onClick={toggleColorMode}
            color={{
              base: colorMode === 'light' ? 'black' : 'yellow',
              lg: colorMode === 'light' ? 'black' : 'white'
            }}
            _active={{ bg: 'none', color: 'none' }}
            _hover={{
              lg: {
                bg: finalBg(
                  'purple.600',
                  'whiteAlpha.300',
                  'gray.500',
                  'whiteAlpha.400'
                ),
                transition: '0.5s',
                color: colorMode === 'light' ? 'white' : 'yellow'
              }
            }}
            size={{ base: 'sm', sm: 'md' }}
            fontSize={{ base: '16px', md: '24px', lg: '20px' }}
          >
            {colorMode === 'light' ? (
              <MoonIcon />
            ) : (
              <FontAwesomeIcon icon={faSun} size='1x' />
            )}
          </Button>

          <Flex id={Styles.navLinks}>
            <Hide below='lg'>
              {nav_items.map(({ label, path, className }, i) => (
                <AnchorLink
                  key={i}
                  spy={true}
                  smooth={true}
                  offset={changeSectionOffset(path)}
                  // duration={1000} // Uncomment if needed
                  to={`${path}`}
                  className={className}
                // activeClass='active'
                >
                  <Text className={Styles.navLinkCommon}>{label}</Text>
                </AnchorLink>
              ))}
            </Hide>

            <Button
              id='resume-button-1'
              className='nav-link resume'
              bg='none'
              p='0'
              _hover={{ bg: 'none' }}
              _focus={{ bg: 'none' }}
              _active={{ bg: 'none' }}
              onClick={handleResume}
            >
              <Link
                id='resume-link-1'
                _hover={{ textDecor: 'none' }}
                href={MyResume}
                download='Sanket_Potdar_Resume'
              >
                <Hide below='lg'>
                  <Text className={Styles.navLinkCommon}>Resume</Text>
                </Hide>

                <Show below='lg'>
                  <Text
                    p='0'
                    size='md'
                    fontWeight='bold'
                    className={Styles.navLinkCommon}
                    bg='none'
                    _hover={{ bg: 'none' }}
                    fontSize={{ base: '16px', md: '24px' }}
                  >
                    <FontAwesomeIcon icon={faDownload} size='1x' />
                  </Text>
                </Show>
              </Link>
            </Button>
          </Flex>
        </HStack>
      </Flex>

      <Show below='lg'>
        <Flex
          className={Styles.miniNavMenu}
          bg={
            colorMode === 'light'
              ? 'rgba(159, 122, 234, 0.4)'
              : 'rgba(107, 70, 193, 0.4)'
          }
        // bg='rgba(155, 155, 155, 0.4)'
        >
          {nav_items.map(({ path, icon, className }, i) => (
            <AnchorLink
              key={i}
              spy={true}
              smooth={true}
              offset={changeSectionOffset(path)}
              // duration={1000} // Uncomment if needed
              to={`${path}`}
              onSetActive={(e) => setNavRoute(e)}
            >
              {/* <Tooltip
              hasArrow
              label={label}
              fontSize={'md'}
              openDelay={1000}
            > */}
              <Button
                className={className}
                bg='none'
                // _active={{ bg: 'none', color: 'none' }}
                // _focus={{ bg: 'none', color: 'none' }}
                color={path === navRoute ? 'purple.600' : 'auto'}
                transform={path === navRoute ? 'scale(1.5)' : 'auto'}
                p='0'
                size='md'
                fontWeight='bold'
              >
                <FontAwesomeIcon icon={icon} />
              </Button>
              {/* </Tooltip> */}
            </AnchorLink>
          ))}
        </Flex>
      </Show>
    </>
  );
};

export default Navbar;
